using System.Collections.Generic;
using System.IO;
using HiddenHarbours.Art.Editor;
using UnityEngine;

namespace HiddenHarbours.App.Editor
{
    /// <summary>
    /// <b>NINE MILE CREEK'S ROADS ON G3, IN ROAD KIT V4 (NMC H4), AS THE EDITOR READS THEM.</b> The network file is
    /// generated by <c>tools/nmc-roads/network.cjs</c> from G3's plan as the game holds it (the <c>nmc.plan.*</c>
    /// options of <c>KeyScene_nmc_wharf</c>) and from G3's height and still water: every route by id with its kit
    /// class, width, surface and line in world metres (y north), the three deck bridges, the junctions, and the west
    /// edge where Route 91 leaves for Rice Point. This reads it; nothing here writes it, and nothing here paints.
    ///
    /// <para>A route's <see cref="Route.From"/> says where in the plan it came from: <c>roads[i]</c> for the plan's
    /// nineteen roads, <c>lots.*[i].drives[k]</c> for a lot's own drives, walks and courts. The plan's lot rule
    /// ("every lot stands clear of every road corridor (3 m)") is held against the first kind only.</para>
    /// </summary>
    public static class NineMileCreekRoadNetwork
    {
        public const string FilePath = "Assets/_Project/Data/Terrain/NineMileCreekRoads/NineMileCreekRoadNetwork.json";
        public const string Schema = "hidden-harbours/nmc-road-network@1";

        /// <summary>The plan's lot rule's clearance, metres: a lot box to a road corridor's carriageway edge.</summary>
        public const float LotCorridorClearanceMetres = 3f;

        /// <summary>
        /// The classes whose carriageway is a road corridor in the lot rule's sense. Not <c>town</c>: a town street's
        /// buildings front its walk (the key scenes stand them at the back of the walk), so for a town street the
        /// lots only keep out of the carriageway. Not the walks, boardwalks and footpaths, which are not roads.
        /// </summary>
        public static readonly string[] CorridorClasses = { "route", "paved", "street", "lane" };

        public sealed class Route
        {
            public string Id, Part, From, Class, Surface, Ends, Clip;
            public float Width;
            public Vector2[] Points;

            public float HalfWidth => Width * 0.5f;

            /// <summary>One of the plan's nineteen roads (or a piece of one), not a lot's own drive.</summary>
            public bool IsPlanRoad => From != null && From.StartsWith("roads[");

            public bool IsCorridor => IsPlanRoad && System.Array.IndexOf(CorridorClasses, Class) >= 0;

            /// <summary>From the carriageway's edge to the rectangle, metres; negative where the carriageway reaches
            /// into it. The ends are taken round: a flat end only ever lies farther off, so the measure errs close.</summary>
            public float EdgeDistanceTo(Rect box)
            {
                float best = float.MaxValue;
                for (int i = 0; i + 1 < Points.Length; i++)
                    best = Mathf.Min(best, SegmentToRect(Points[i], Points[i + 1], box));
                return best - HalfWidth;
            }

            public override string ToString() => Part == null ? Id : Id + " (" + Part + ")";
        }

        public sealed class Bridge
        {
            public string Id, On, Over, Kind, Prefab;
            public float Width, StartS, EndS, Span, Deck;
            public Vector2 A, B;

            /// <summary>The deck you stand on, in world metres: its seats' line at the bridge's width, squared to the
            /// axes (the StandablePlatform's footprint).</summary>
            public Rect Footprint;
        }

        /// <summary>
        /// One clearance the network keeps in a hedge: a side of a road's hedge cleared along x (<see cref="Clear"/>) or
        /// gated (<see cref="Gates"/>, each a gate's span, the gates held and so not dressed), or a field boundary's
        /// hedge cut back to its line (<see cref="Line"/>). The fields' and the playground's entries are the plan's and
        /// are not read here.
        /// </summary>
        public sealed class Clearance
        {
            public string Id, Side;
            public Vector2 Clear;
            public List<Vector2> Gates = new List<Vector2>();
            public Vector2[] Line;
        }

        public sealed class Network
        {
            public string Schema;
            public List<Route> Routes = new List<Route>();
            public List<Bridge> Bridges = new List<Bridge>();
            public List<string> Held = new List<string>();
            public List<Clearance> Clearances = new List<Clearance>();
            public int Fords;
            public string WestEdgeRoute;
            public Vector2 WestEdgeAt;

            public IEnumerable<Route> All(string id)
            {
                foreach (Route r in Routes)
                    if (r.Id == id) yield return r;
            }
        }

        static Network _cached;

        /// <summary>The network, read once per domain. <paramref name="root"/> is the project folder (the editor's
        /// working directory when omitted).</summary>
        public static Network Load(string root = null)
        {
            if (_cached != null && root == null) return _cached;
            string path = root == null ? FilePath : System.IO.Path.Combine(root, FilePath);
            var json = MiniJson.Parse(File.ReadAllText(path)) as Dictionary<string, object>;
            var net = new Network { Schema = MiniJson.String(json, "schema") };

            foreach (object o in MiniJson.List(json, "routes"))
                net.Routes.Add(new Route
                {
                    Id = MiniJson.String(o, "id"),
                    Part = MiniJson.String(o, "part"),
                    From = MiniJson.String(o, "from"),
                    Class = MiniJson.String(o, "cls"),
                    Surface = MiniJson.String(o, "surf"),
                    Ends = MiniJson.String(o, "ends"),
                    Clip = MiniJson.String(o, "clip"),
                    Width = MiniJson.Float(o, "w"),
                    Points = Points(MiniJson.List(o, "pts")),
                });

            foreach (object o in MiniJson.List(json, "bridges"))
                net.Bridges.Add(new Bridge
                {
                    Id = MiniJson.String(o, "id"),
                    On = MiniJson.String(o, "on"),
                    Over = MiniJson.String(o, "over"),
                    Kind = MiniJson.String(o, "kind"),
                    Prefab = MiniJson.String(o, "prefab"),
                    Width = MiniJson.Float(o, "width"),
                    StartS = MiniJson.Float(o, "sA"),
                    EndS = MiniJson.Float(o, "sB"),
                    Span = MiniJson.Float(o, "span"),
                    Deck = MiniJson.Float(o, "deck"),
                    A = Point(MiniJson.List(o, "a")),
                    B = Point(MiniJson.List(o, "b")),
                    Footprint = Box(MiniJson.Dict(o, "footprint")),
                });

            foreach (object o in MiniJson.List(json, "clearances"))
            {
                string id = MiniJson.String(o, "id");
                if (!id.StartsWith("hedge.", System.StringComparison.Ordinal)) continue;
                var c = new Clearance { Id = id, Side = MiniJson.String(o, "side") };
                if (MiniJson.Has(o, "clear")) c.Clear = Point(MiniJson.List(o, "clear"));
                foreach (object g in MiniJson.List(o, "gates") ?? new List<object>()) c.Gates.Add(Point(MiniJson.List(g, "x")));
                if (MiniJson.Has(o, "pts")) c.Line = Points(MiniJson.List(o, "pts"));
                net.Clearances.Add(c);
            }

            foreach (object o in MiniJson.List(json, "held")) net.Held.Add(MiniJson.String(o, "id"));
            net.Fords = MiniJson.List(json, "fords")?.Count ?? -1;
            var west = MiniJson.Dict(json, "westEdge");
            net.WestEdgeRoute = MiniJson.String(west, "route");
            net.WestEdgeAt = Point(MiniJson.List(west, "at"));

            if (root == null) _cached = net;
            return net;
        }

        static Vector2 Point(List<object> xy) => new Vector2((float)(double)xy[0], (float)(double)xy[1]);

        static Rect Box(Dictionary<string, object> box) =>
            new Rect(MiniJson.Float(box, "x"), MiniJson.Float(box, "y"), MiniJson.Float(box, "w"), MiniJson.Float(box, "h"));

        static Vector2[] Points(List<object> list)
        {
            var pts = new Vector2[list.Count];
            for (int i = 0; i < pts.Length; i++) pts[i] = Point((List<object>)list[i]);
            return pts;
        }

        // ---- geometry ---------------------------------------------------------------------------------------------

        /// <summary>From a segment to a rectangle, metres (0 where they meet). Two convex shapes apart are nearest at a
        /// vertex of one, so the segment's ends against the box and the box's corners against the segment are the
        /// whole answer.</summary>
        public static float SegmentToRect(Vector2 a, Vector2 b, Rect box)
        {
            if (SegmentMeetsRect(a, b, box)) return 0f;
            float d = Mathf.Min(PointToRect(a, box), PointToRect(b, box));
            d = Mathf.Min(d, PointToSegment(new Vector2(box.xMin, box.yMin), a, b));
            d = Mathf.Min(d, PointToSegment(new Vector2(box.xMax, box.yMin), a, b));
            d = Mathf.Min(d, PointToSegment(new Vector2(box.xMin, box.yMax), a, b));
            d = Mathf.Min(d, PointToSegment(new Vector2(box.xMax, box.yMax), a, b));
            return d;
        }

        public static float PointToRect(Vector2 p, Rect box)
        {
            float dx = Mathf.Max(box.xMin - p.x, 0f, p.x - box.xMax);
            float dy = Mathf.Max(box.yMin - p.y, 0f, p.y - box.yMax);
            return Mathf.Sqrt(dx * dx + dy * dy);
        }

        public static float PointToSegment(Vector2 p, Vector2 a, Vector2 b)
        {
            Vector2 ab = b - a;
            float len2 = ab.x * ab.x + ab.y * ab.y;
            float t = len2 <= 0f ? 0f : Mathf.Clamp01(((p.x - a.x) * ab.x + (p.y - a.y) * ab.y) / len2);
            Vector2 q = a + ab * t;
            return Mathf.Sqrt((p.x - q.x) * (p.x - q.x) + (p.y - q.y) * (p.y - q.y));
        }

        /// <summary>Liang–Barsky: does the segment cross or touch the rectangle?</summary>
        static bool SegmentMeetsRect(Vector2 a, Vector2 b, Rect box)
        {
            float t0 = 0f, t1 = 1f, dx = b.x - a.x, dy = b.y - a.y;
            return Clip(-dx, a.x - box.xMin, ref t0, ref t1) && Clip(dx, box.xMax - a.x, ref t0, ref t1)
                && Clip(-dy, a.y - box.yMin, ref t0, ref t1) && Clip(dy, box.yMax - a.y, ref t0, ref t1);
        }

        static bool Clip(float p, float q, ref float t0, ref float t1)
        {
            if (p == 0f) return q >= 0f;
            float r = q / p;
            if (p < 0f) { if (r > t1) return false; if (r > t0) t0 = r; }
            else { if (r < t0) return false; if (r < t1) t1 = r; }
            return true;
        }
    }
}
